<script lang="ts">
 import ModelPicker from './ModelPicker.svelte';
 import ProjectBranch from './ProjectBranch.svelte';
 import {autosize} from '$lib/blux/autosize';
 import {request,errorText} from '$lib/blux/api';import {folderName,type ContextChoice} from '$lib/blux/context';import type {AgentAdapter} from '$lib/blux/types';import type {Collaboration} from '$lib/blux/collaborations';import {agentOptions,type AgentInfo} from '$lib/blux/agents';import Select from './Select.svelte';import Icon from './Icon.svelte';import MessageInput from './MessageInput.svelte';
 export let open=false;export let collaboration:Collaboration|null=null;export let project='';export let agents:AgentInfo[]=[];export let onCreated:(id:string)=>void=()=>{};export let onTaskCreated:()=>void=()=>{};
 let selectedModel='';let selectedProvider='';let selectedEffort='';let dialog:HTMLDialogElement;let title='';let prompt='';let adapter:AgentAdapter='codex';const mode='explore';let error='';let pending=false;let picking=false;let key='';let fingerprint='';let wasOpen=false;let selectedContexts:ContextChoice[]=[];let contextMenuOpen=false;
 $: if(open&&!wasOpen){wasOpen=true;selectedModel='';selectedProvider='';selectedEffort='';title='';prompt='';selectedContexts=[];error='';key='';fingerprint='';} $: if(!open)wasOpen=false;
 $: if(dialog){if(open&&!dialog.open)dialog.showModal();else if(!open&&dialog.open)dialog.close();}
 async function selectFolder(){picking=true;error='';try{const r=await fetch('/api/v1/projects/select',{method:'POST',signal:AbortSignal.timeout(125000)});const v=await r.json();if(!r.ok)throw new Error(v.error?.message||'无法选择项目');if(!v.canceled)project=v.path;}catch(e){error=errorText(e)}finally{picking=false}}
 async function submit(){if(pending||!prompt.trim()||collaboration&&contextMenuOpen)return;if(!collaboration&&!project){error='请选择项目文件夹。';return};const payload=collaboration?{title:title.trim(),prompt:prompt.trim(),adapter,mode,model:selectedModel,model_provider:selectedProvider,reasoning_effort:selectedEffort,context_ids:selectedContexts.map(v=>v.id)}:{title:title.trim(),goal:prompt.trim(),repository_path:project};const fp=JSON.stringify([collaboration?.id,payload]);if(fp!==fingerprint){fingerprint=fp;key=crypto.randomUUID()};pending=true;error='';try{const result=await request<{id?:string}>(collaboration?`/collaborations/${collaboration.id}/tasks`:'/collaborations',{method:'POST',headers:{'Idempotency-Key':key},body:JSON.stringify(payload)});open=false;if(collaboration)onTaskCreated();else if(result.id)onCreated(result.id);}catch(e){error=errorText(e)}finally{pending=false}}
</script>
<dialog bind:this={dialog} class="collaboration-dialog" class:agent-task-dialog={!!collaboration} aria-label={collaboration?'创建 Agent 任务':'新建协作'} on:cancel={(e)=>{if(pending||picking)e.preventDefault();else open=false}} on:close={()=>open=false}>
 <header><div><h2 id={collaboration?'agent-task-dialog-title':'collaboration-dialog-title'}>{collaboration?'指派任务':'新建协作'}</h2>{#if collaboration}<div class="task-dialog-context"><span title={collaboration.title}>{collaboration.title}</span><span class="task-dialog-project"><Icon name="folder" size={13}/>{folderName(collaboration.repository_path)}</span><ProjectBranch project={collaboration.repository_path}/></div>{/if}</div><button type="button" class="ui-icon-button" disabled={pending||picking} aria-label="关闭创建窗口" on:click={()=>open=false}><Icon name="close"/></button></header>
 <div class="collaboration-dialog-form">
  <label class="sr-only" for={collaboration?'agent-task-title':'collaboration-title'}>{collaboration?'任务名称':'协作名称'}</label><input id={collaboration?'agent-task-title':'collaboration-title'} class="collaboration-title-input" bind:value={title} placeholder={collaboration?'任务名称（可选）':'协作名称'} maxlength="120" disabled={pending}/>
  <div class="collaboration-prompt"><label class="sr-only" for={collaboration?'agent-task-prompt':'collaboration-prompt'}>{collaboration?'任务描述':'协作目标'}</label>{#if collaboration}<div class="dialog-task-composer"><MessageInput inputID="agent-task-prompt" showSend={false} showManageContext={false} spacious bind:prompt project={collaboration.repository_path} bind:selectedContexts bind:menuOpen={contextMenuOpen} disabled={pending} onSubmit={()=>void submit()}><svelte:fragment slot="tools"><Select ariaLabel="指派 Agent" bind:value={adapter} options={agentOptions(agents)} disabled={pending} compact/></svelte:fragment><svelte:fragment slot="settings"><ModelPicker {adapter} project={collaboration.repository_path} bind:model={selectedModel} bind:provider={selectedProvider} bind:effort={selectedEffort} disabled={pending}/></svelte:fragment></MessageInput></div>{:else}<textarea id="collaboration-prompt" bind:value={prompt} use:autosize={prompt} rows="1" placeholder="描述共同目标，再为不同 Agent 分配任务…" disabled={pending}></textarea>{/if}
  {#if !collaboration}<div class="collaboration-prompt-footer"><button type="button" class="choose-collaboration-project" on:click={()=>void selectFolder()} disabled={pending||picking}><Icon name="folder" size={16}/>{picking?'正在选择…':folderName(project)||'选择项目文件夹'}</button><ProjectBranch {project}/></div>{/if}</div>
  {#if collaboration&&agents.find(a=>a.id===adapter)?.available===false}<p class="dialog-agent-notice">{agents.find(a=>a.id===adapter)?.reason}</p>{/if}
  {#if error}<p class="inline-error" role="alert">{error}</p>{/if}
  <footer><button type="button" class="subtle-button" disabled={pending||picking} on:click={()=>open=false}>取消</button><button class="primary-button" type="button" on:click={()=>void submit()} disabled={pending||picking||!!collaboration&&contextMenuOpen||!prompt.trim()||!collaboration&&!project||!!collaboration&&agents.find(a=>a.id===adapter)?.available===false}>{pending?'创建中…':collaboration?'创建任务':'创建'}</button></footer>
 </div>
</dialog>
